window.QUESTION_CHOICE_REVIEW={"CQZSB-ENG-20261016-065":{"mode":"ambiguous-single","acceptedChoices":["A","C"],"preferredAnswer":"A","analysis":"sheep 和 deer 的单复数同形，都可以表示在山坡上吃草的多只动物。原题给 A，题干未写出可用于区分绵羊与鹿的特征。"},"CQZSB-ENG-20261016-066":{"mode":"single","stem":"The young man made a ____ to donate half his income to charity every year. Which word best emphasizes his long-term dedication to this cause?","answer":"C","acceptedChoices":["C"],"analysis":"C。make a commitment to do sth. 强调承诺并持续投入。本题明确问 long-term dedication，最贴切的是 commitment。promise 侧重许诺，decision 侧重作出决定，plan 侧重安排。","topicTitle":"名词辨析 · make a commitment to do sth.","lesson":{"translation":"这个年轻人作出一项____，每年把一半收入捐给慈善事业。哪个词最能突出他对这项事业的长期投入？","optionAnalysis":{"A":{"meaning":"承诺","reason":"make a promise to do sth. 侧重许诺。这里问哪个词最强调长期投入。"},"B":{"meaning":"决定","reason":"make a decision to do sth. 侧重作出决定。"},"C":{"meaning":"郑重承诺、持续投入","reason":"make a commitment to do sth. 强调承担责任及持续投入，呼应 long-term dedication。"},"D":{"meaning":"计划","reason":"make a plan to do sth. 侧重制定安排。"}},"steps":["先看题目要求强调哪一种含义。","long-term dedication 指长期投入，因此选 commitment。"],"memoryTip":"make a commitment to do sth. 意为承诺做某事。"}},"CQZSB-ENG-20261016-070":{"mode":"ambiguous-single","acceptedChoices":["B","D"],"preferredAnswer":"D","analysis":"take immediate measures 与 take immediate action 都表示立即采取行动。原题参考 D，B 也可以成立；单数 measure 或 step 直接放在这里缺少限定词。"},"CQZSB-ENG-20261016-087":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"preferredAnswer":"A","analysis":"twice as large as 和 two times as large as 都能表示大小是另一座图书馆的两倍。原题参考 A，twice 更简洁常见。"},"CQZSB-ENG-20261016-099":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"analysis":"anybody 表示班里随便找谁都可以，和 everyone 呼应得更直接。somebody 表示可以找某个人帮忙，与后半句也相容。"},"CQZSB-ENG-20261016-105":{"mode":"ambiguous-single","acceptedChoices":["A","C"],"preferredAnswer":"A","analysis":"Anyone who 表示任何一个违反校规的人，Everyone who 表示所有违反校规的人，句意在这里都成立。原题参考 A。"},"CQZSB-ENG-20261016-110":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"analysis":"be beneficial to 常用来引出受益的对象。beneficial for 也可表示有利于某项发展，此句缺少足以排除它的条件。"},"CQZSB-ENG-20261016-111":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"preferredAnswer":"B","analysis":"through hard work 表示通过努力，by hard work 也可表示以努力作为手段。原题参考 B。"},"CQZSB-ENG-20261016-113":{"mode":"ambiguous-single","acceptedChoices":["B","C"],"preferredAnswer":"C","analysis":"due to 可中性地说明会议推迟的原因，原题参考 C。thanks to 也可用于负面结果或反讽；使用这种语气时 B 亦可成立。"},"CQZSB-ENG-20261016-119":{"mode":"ambiguous-single","acceptedChoices":["A","C"],"analysis":"in contrast with 与 by contrast with 都可以引出对照对象。此句比较线上学习和传统教学，没有给出能排除其中一个表达的条件。"},"CQZSB-ENG-20261016-140":{"mode":"ambiguous-single","acceptedChoices":["B","C"],"analysis":"tuition fees 具体指应付的学费，tuition costs 指学费支出。两个表达都可用于说明学生因高学费而烦恼。"},"CQZSB-ENG-20261017-006":{"mode":"ambiguous-single","acceptedChoices":["B","D"],"analysis":"Both of them 和 The two of them 都表示这两扇窗，后面都可以接 face。Both of them 更简洁常用。"},"CQZSB-ENG-20261017-021":{"mode":"ambiguous-single","acceptedChoices":["A","D"],"analysis":"private matters 和 private affairs 都可指私事，均可作 discussed 的宾语。"},"CQZSB-ENG-20261017-031":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"analysis":"lack of time 是常见搭配，shortage of time 也能表示时间不足。此句没有规定使用哪一个搭配。"},"CQZSB-ENG-20261017-033":{"mode":"ambiguous-single","acceptedChoices":["C","D"],"analysis":"come to a conclusion 更贴合“讨论后得出结论”，come to a judgment 也可表示形成判断。A、B 无法在此表达讨论者未能得出判断。"},"CQZSB-ENG-20261017-041":{"mode":"ambiguous-single","acceptedChoices":["B","C"],"analysis":"position 和 post 都可以表示职位。此句只说在知名公司找到工作，没有区分两者的语境。"},"CQZSB-ENG-20261017-046":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"analysis":"of French birth 表示出生于法国，of French origin 可以表示法国血统或背景。题干没说所指的是出生地还是出身。"},"CQZSB-ENG-20261018-035":{"mode":"ambiguous-single","acceptedChoices":["A","B","C","D"],"preferredAnswer":"A","analysis":"a few white hairs 表示几根白发，原题参考 A。题干没要求逐根计数，也没限定白发是否比以前更多，因此另外三个表达也可在相应语境中成立。"},"CQZSB-ENG-20261018-151":{"mode":"ambiguous-single","acceptedChoices":["A","B"],"preferredAnswer":"A","analysis":"Little progress 强调进展甚微，最直接地呼应还需更多措施，原题参考 A。A little progress 表示已有少量进展，但仍然需要更多措施，语义也能成立。"},"CQZSB-ENG-20261018-165":{"mode":"ambiguous-single","acceptedChoices":["A","B","C"],"preferredAnswer":"C","analysis":"500 meters 是长度单位，可以回答河有多长、多宽或多深。原题参考 C，题干没有指定问哪个维度。"},"CQZSB-20261027-d6eea3fb0346ea":{"mode":"ambiguous-single","acceptedChoices":["B","C"],"preferredAnswer":"C","analysis":"原题 B、C 两项都印为 2，配套答案选 C。通分后为 (2x²−2x)/(x²+x+2)，极限为 2。两个选项文字相同，应保留原题记录并接受任一项。"},"MATH-C1-20261104-125-例10":{"mode":"ambiguous-single","acceptedChoices":["B","C"],"analysis":"在 0 左极限为 1，右极限为 −1，所以 0 是跳跃间断点，也属于第一类间断点。B 更具体，原题却同时列了它的上位分类 C。"},"CQZSB-AUDIT-3a790d9fab494528":{"mode":"ambiguous-single","acceptedChoices":["B","D"],"analysis":"极限为 2f(3)=−2，原选项 B（2f(3)）和 D（−2）等价。"},"QFW-26-LAST800-COMPUTER-CH03-066":{"mode":"multi","type":"多选题","answer":"ACD","analysis":"VGA 显示器使用的三基色为红、绿、蓝（RGB），应同时选择 A、C、D。"}};
